import { useState } from "react";
import axios from "axios";
import { TextField, Button, Snackbar, Typography, Container, Box } from "@mui/material";

const SendOTP = () => {
    const [email, setEmail] = useState("");
    const [message, setMessage] = useState("");
    const [openSnackbar, setOpenSnackbar] = useState(false);
    const [loading, setLoading] = useState(false);

    const handleSendOTP = async () => {
        if (!email) {
            setMessage("Veuillez entrer un email.");
            setOpenSnackbar(true);
            return;
        }

        setLoading(true);
        try {
            const res = await axios.post("http://localhost:5000/api/candidats/send-otp", { email });
            setMessage(res.data.message || "Code envoyé avec succès !");
        } catch (error) {
            setMessage(error.response?.data?.error || "Erreur lors de l'envoi du code.");
        } finally {
            setLoading(false);
            setOpenSnackbar(true);
        }
    };

    return (
        <Container maxWidth="sm">
            <Box sx={{ textAlign: 'center', marginTop: 5 }}>
                <Typography variant="h5" gutterBottom>
                    Recevoir votre code de sécurité
                </Typography>
                <TextField
                    fullWidth
                    label="Entrez votre email"
                    type="email"
                    variant="outlined"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    sx={{ marginBottom: 2 }}
                />
                <Button
                    onClick={handleSendOTP}
                    variant="contained"
                    color="primary"
                    fullWidth
                    disabled={loading}
                >
                    {loading ? "Envoi en cours..." : "Envoyer le code"}
                </Button>
            </Box>

            <Snackbar
                open={openSnackbar}
                autoHideDuration={4000}
                onClose={() => setOpenSnackbar(false)}
                message={message}
            />
        </Container>
    );
};

export default SendOTP;
